import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Union

import boto3
from boto3.session import Session


def _to_datetime(value: Optional[Union[str, datetime]]) -> Optional[datetime]:
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.astimezone(timezone.utc) if value.tzinfo else value.replace(tzinfo=timezone.utc)
    s = value.strip()
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    return dt.astimezone(timezone.utc) if dt.tzinfo else dt.replace(tzinfo=timezone.utc)


def _normalize_metric_stat_points(results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for r in results:
        id_ = r.get("Id")
        label = r.get("Label")
        status = r.get("StatusCode")
        timestamps = r.get("Timestamps", []) or []
        values = r.get("Values", []) or []
        unit = r.get("Messages", [])
        points = [
            {"timestamp": ts, "value": val}
            for ts, val in zip(timestamps, values)
        ]
        normalized.append(
            {
                "id": id_,
                "label": label,
                "status": status,
                "points": points,
                "messages": unit,
            }
        )
    return normalized


def compare_metrics(
    metric_name: str,
    namespace: str,
    stat: str,
    resource_a: Dict[str, str],
    resource_b: Dict[str, str],
    start_time: Optional[Union[str, datetime]] = None,
    end_time: Optional[Union[str, datetime]] = None,
    period: int = 300,
    region_name: Optional[str] = None,
    unit: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Compare Amazon CloudWatch metric values for two resources or dimension filters
    over the same time window using GetMetricData.

    resource_a/resource_b:
        Dict of CloudWatch dimensions, e.g. {"InstanceId": "i-1234567890abcdef0"}
    """
    region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    session: Session = boto3.Session(region_name=region_name)
    client = session.client("cloudwatch")

    end_dt = _to_datetime(end_time) or datetime.now(timezone.utc)
    start_dt = _to_datetime(start_time) or (end_dt - timedelta(hours=1))

    def build_query(metric_id: str, dims: Dict[str, str]) -> Dict[str, Any]:
        return {
            "Id": metric_id,
            "MetricStat": {
                "Metric": {
                    "Namespace": namespace,
                    "MetricName": metric_name,
                    "Dimensions": [
                        {"Name": k, "Value": v} for k, v in sorted(dims.items(), key=lambda kv: kv[0])
                    ],
                },
                "Period": int(period),
                "Stat": stat,
                **({"Unit": unit} if unit else {}),
            },
            "ReturnData": True,
        }

    response = client.get_metric_data(
        MetricDataQueries=[
            build_query("m1", resource_a),
            build_query("m2", resource_b),
        ],
        StartTime=start_dt,
        EndTime=end_dt,
        ScanBy="TimestampAscending",
        MaxDatapoints=100800,
    )

    results = response.get("MetricDataResults", [])
    normalized = _normalize_metric_stat_points(results)

    series_a = next((r for r in normalized if r["id"] == "m1"), {"points": []})
    series_b = next((r for r in normalized if r["id"] == "m2"), {"points": []})

    def summarize(points: List[Dict[str, Any]]) -> Dict[str, Any]:
        vals = [p["value"] for p in points if p.get("value") is not None]
        if not vals:
            return {"count": 0, "min": None, "max": None, "avg": None, "sum": None, "latest": None}
        latest_point = max(points, key=lambda p: p["timestamp"])
        return {
            "count": len(vals),
            "min": min(vals),
            "max": max(vals),
            "avg": sum(vals) / len(vals),
            "sum": sum(vals),
            "latest": latest_point["value"],
        }

    summary_a = summarize(series_a["points"])
    summary_b = summarize(series_b["points"])

    def diff(a: Optional[float], b: Optional[float]) -> Optional[float]:
        if a is None or b is None:
            return None
        return a - b

    comparison = {
        "metric": {"namespace": namespace, "name": metric_name, "stat": stat, "unit": unit, "period": period},
        "window": {"start": start_dt.isoformat(), "end": end_dt.isoformat()},
        "resource_a": {"dimensions": resource_a, "series": series_a, "summary": summary_a},
        "resource_b": {"dimensions": resource_b, "series": series_b, "summary": summary_b},
        "delta": {
            "avg": diff(summary_a["avg"], summary_b["avg"]),
            "sum": diff(summary_a["sum"], summary_b["sum"]),
            "latest": diff(summary_a["latest"], summary_b["latest"]),
            "max": diff(summary_a["max"], summary_b["max"]),
            "min": diff(summary_a["min"], summary_b["min"]),
        },
        "raw_response": response,
    }
    return comparison
